function gridPaths(grid) {
  const rows = grid.length, cols = grid[0].length, dp = grid.map(row => row.map(() => 0)) //@init
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 1) continue //@wall
      if (r === 0 && c === 0) { dp[r][c] = 1; continue } //@start
      dp[r][c] = (r > 0 ? dp[r - 1][c] : 0) + (c > 0 ? dp[r][c - 1] : 0) //@fill
    }
  }
  return dp[rows - 1][cols - 1] //@done
}

